type State = { readonly version: number; readonly balances: Readonly<Record<number, number>> };
type Action = { type: 'TRANSFER'; from: number; to: number; amt: number }
              | { type: 'NOOP' };

// TS enforces purity here: `state` is readonly, and the compiler rejects mutation.
function apply(state: State, a: Action): State {
  if (a.type === 'NOOP') return state;
  const f = state.balances[a.from];
  if (f === undefined || f < a.amt) return state;
  return { version: state.version + 1,
           balances: { ...state.balances, [a.from]: f - a.amt, [a.to]: (state.balances[a.to] ?? 0) + a.amt } };
}

